/* Registry mapping and payroll payment rule. No inferred social affiliations. */
(function(root){'use strict';
function normalizeSiret(value){const s=String(value??'').replace(/\s/g,'');if(!/^\d{14}$/.test(s)||/^0+$/.test(s))throw Error('Saisissez un SIRET de 14 chiffres.');return s;}
function paymentDate(period){const m=/^(\d{4})-(0[1-9]|1[0-2])$/.exec(String(period));if(!m||Number(m[1])<1900||Number(m[1])>9998)throw Error('Période de paie invalide.');let year=Number(m[1]),month=Number(m[2])+1;if(month===13){month=1;year++;}return String(year).padStart(4,'0')+'-'+String(month).padStart(2,'0')+'-05';}
function formatDate(date){const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(date));return m?m[3]+'/'+m[2]+'/'+m[1]:'Non enregistrée';}
function mapRegistry(data,requested){const s=normalizeSiret(requested);if(!data||!Array.isArray(data.results))throw Error('Réponse du registre non reconnue.');for(const legal of data.results){if(String(legal.siren||'')!==s.slice(0,9))continue;const matches=[...(Array.isArray(legal.matching_etablissements)?legal.matching_etablissements:[]),...(legal.siege?[legal.siege]:[])];const est=matches.find(e=>String(e.siret)===s);if(!est)continue;const candidates=Array.from(new Set([...(Array.isArray(est.liste_idcc)?est.liste_idcc:[]),...(Array.isArray(legal.complements?.liste_idcc)?legal.complements.liste_idcc:[])].map(String)));const street=[est.numero_voie,est.indice_repetition,est.type_voie,est.libelle_voie].filter(Boolean).join(' ');const address=est.adresse||[est.complement_adresse,street,[est.code_postal,est.libelle_commune].filter(Boolean).join(' ')].filter(Boolean).join(', ');return{name:legal.nom_complet||legal.nom_raison_sociale||'',siret:s,siren:String(legal.siren),address:address||'',ape:est.activite_principale||'',legalForm:legal.nature_juridique||'',creationDate:est.date_creation||'',registryState:est.etat_administratif||'',idccCandidates:candidates.join(', '),source:'https://recherche-entreprises.api.gouv.fr',sourceUrl:'https://annuaire-entreprises.data.gouv.fr/etablissement/'+s};}throw Error('Aucun établissement correspondant exactement à ce SIRET n’a été trouvé. La saisie manuelle reste possible.');}
const api={normalizeSiret,paymentDate,formatDate,mapRegistry};if(typeof module!=='undefined'&&module.exports)module.exports=api;root.CompanyUtils=api;
})(typeof globalThis!=='undefined'?globalThis:this);
